"""Write the 10 s test signal data/sweep10s.raw (mono float32, 48 kHz), generated by this script and fully deterministic.

It is the hardest material the accuracy tests use: wide-band content, levels from quiet to loud, high crest factors,
abrupt starts and stops, and decays into silence. The whole signal is scaled by LEVEL = 0.1 (-20 dB), the level of a
typical guitar DI (peak -20 dBFS), and the quietest parts are about 26 dB below the loudest. The error between two correct
float32 implementations is about the same at every level while the output energy falls with the level, so the
error-to-signal ratio is largest for quiet material. The amplitudes below are before the scaling.

    0.0 to 1.0 s   pink noise whose level rises from 0.02 to 0.5 on a logarithmic ramp
    1.0 to 2.0 s   exponential sine sweep downwards, 20 kHz to 20 Hz, amplitude 0.2
    2.0 to 4.0 s   exponential sine sweep upwards, 20 Hz to 20 kHz, amplitude 0.9
    4.0 to 5.5 s   64 sines with random phases, log-spaced from 80 Hz to 8 kHz, peak 0.8
    5.5 to 7.0 s   white noise bursts of 100 ms with 100 ms of silence between, amplitude alternating 0.95 and 0.2
    7.0 to 8.5 s   six plucked strings (Karplus-Strong, E2 A2 D3 G3 B3 E4), 0.25 s each, peak 0.7
    8.5 to 9.5 s   frequency-modulated tone (440 Hz, deviation 200 Hz, 5 Hz) with amplitude modulation from 0.1 to 0.9
    9.5 to 10  s   silence with one impulse of +0.9 at 9.6 s and one of -0.9 at 9.8 s

The first 2 s hold the quietest and most demanding material: the tests that are too slow to run on the whole signal
(the scalar reference) use only these. Every segment starts and ends with a 1 ms fade, except the impulses. The peak
before scaling is 0.95.

    python tools/make_sweep.py [out.raw]
"""

import sys
from pathlib import Path

import numpy as np

SR = 48_000
LEVEL = 0.1  # overall scaling, see the description above


def _fade(x: np.ndarray, ms: float = 1.0) -> np.ndarray:
    n = int(SR * ms / 1000)
    ramp = np.linspace(0.0, 1.0, n)
    x = x.copy()
    x[:n] *= ramp
    x[-n:] *= ramp[::-1]
    return x


def _exp_sweep(f0: float, f1: float, dur: float, amp: float) -> np.ndarray:
    t = np.arange(int(dur * SR)) / SR
    k = np.log(f1 / f0)
    return amp * np.sin(2 * np.pi * f0 * dur / k * (np.exp(t * k / dur) - 1.0))


def _pink(n: int, rng: np.random.Generator) -> np.ndarray:
    spectrum = np.fft.rfft(rng.standard_normal(n))
    f = np.arange(len(spectrum), dtype=float)
    f[0] = 1.0
    x = np.fft.irfft(spectrum / np.sqrt(f), n)
    return x / np.max(np.abs(x))


def _pluck(freq: float, dur: float, amp: float, rng: np.random.Generator) -> np.ndarray:
    n = int(dur * SR)
    period = int(round(SR / freq))
    buf = rng.uniform(-1, 1, period)
    out = np.empty(n)
    for i in range(n):  # Karplus-Strong: a delay line with averaging
        out[i] = buf[i % period]
        buf[i % period] = 0.498 * (buf[i % period] + buf[(i + 1) % period])
    return amp * out / np.max(np.abs(out))


def make_sweep() -> np.ndarray:
    rng = np.random.default_rng(2)

    up = _fade(_exp_sweep(20.0, 20_000.0, 2.0, 0.9))
    down = _fade(_exp_sweep(20_000.0, 20.0, 1.0, 0.2))

    t = np.arange(int(1.5 * SR)) / SR
    freqs = np.geomspace(80.0, 8000.0, 64)
    multi = sum(np.sin(2 * np.pi * f * t + rng.uniform(0, 2 * np.pi)) for f in freqs)
    multi = _fade(0.8 * multi / np.max(np.abs(multi)))

    bursts = []
    for i in range(int(1.5 / 0.2)):
        amp = 0.95 if i % 2 == 0 else 0.2
        bursts.append(np.concatenate([_fade(amp * rng.uniform(-1, 1, SR // 10)), np.zeros(SR // 10)]))
    bursts = np.concatenate(bursts)
    bursts = np.concatenate([bursts, np.zeros(int(1.5 * SR) - len(bursts))])

    plucks = np.concatenate([_fade(_pluck(f, 0.25, 0.7, rng)) for f in (82.41, 110.0, 146.83, 196.0, 246.94, 329.63)])

    tm = np.arange(SR) / SR
    fm = np.sin(2 * np.pi * 440.0 * tm + (200.0 / 5.0) * np.sin(2 * np.pi * 5.0 * tm))
    am = 0.5 + 0.4 * np.sin(2 * np.pi * 1.0 * tm - np.pi / 2)
    modulated = _fade(am * fm)

    ramp = np.geomspace(0.02, 0.5, SR)
    pink = _fade(ramp * _pink(SR, rng))

    tail = np.zeros(int(0.5 * SR))
    tail[int(0.1 * SR)] = 0.9
    tail[int(0.3 * SR)] = -0.9

    x = (LEVEL * np.concatenate([pink, down, up, multi, bursts, plucks, modulated, tail])).astype("<f4")
    assert len(x) == 10 * SR, len(x)
    assert float(np.max(np.abs(x))) <= 0.95 * LEVEL + 1e-6
    return x


if __name__ == "__main__":
    out = Path(sys.argv[1] if len(sys.argv) > 1 else Path(__file__).resolve().parent.parent / "tests" / "data" / "sweep10s.raw")
    out.parent.mkdir(parents=True, exist_ok=True)
    make_sweep().tofile(out)
    print(f"wrote {out} ({out.stat().st_size} bytes)")
